ALTER TABLE public.pm_expenses ADD COLUMN intake_key text;
CREATE UNIQUE INDEX pe_intake_key_unique ON public.pm_expenses(entity_id,intake_key) WHERE workflow_version=2 AND intake_key IS NOT NULL;
CREATE TABLE public.project_expense_credit_allocations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), invoice_allocation_id uuid NOT NULL REFERENCES public.project_expense_invoice_allocations(id), credit_line_id uuid NOT NULL REFERENCES public.financial_document_lines(id), cost_amount numeric(14,2) NOT NULL CHECK(cost_amount>0), billed_amount numeric(14,2) NOT NULL CHECK(billed_amount>0), vat_amount numeric(14,2) NOT NULL CHECK(vat_amount>=0), actor uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.project_expense_credit_allocations TO authenticated;
GRANT ALL ON public.project_expense_credit_allocations TO service_role;
REVOKE TRUNCATE ON public.project_expense_credit_allocations FROM anon,authenticated;
ALTER TABLE public.project_expense_credit_allocations ENABLE ROW LEVEL SECURITY;
CREATE POLICY pe_credits_read ON public.project_expense_credit_allocations FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.project_expense_invoice_allocations a WHERE a.id=invoice_allocation_id));
DO $$ DECLARE d text; BEGIN
SELECT pg_get_functiondef('public.pe_guard()'::regprocedure) INTO d;
d:=public.pe_replace_once(d,'BEGIN','BEGIN IF TG_OP=''INSERT'' AND NEW.workflow_version<>2 THEN RAISE EXCEPTION ''Use expense workflow actions''; END IF;'); EXECUTE d;
SELECT pg_get_functiondef('public.pe_action(text,jsonb)'::regprocedure) INTO d;
d:=public.pe_replace_once(d,' IF _action=''save'' THEN',' IF _action=''save'' THEN IF eid IS NULL AND nullif(_data->>''intakeKey'','''') IS NOT NULL THEN PERFORM pg_advisory_xact_lock(hashtextextended(''pe-intake:''||(_data->>''intakeKey''),0)); SELECT * INTO e FROM pm_expenses WHERE entity_id=''00000000-0000-4000-a000-000000000001'' AND workflow_version=2 AND intake_key=_data->>''intakeKey'' FOR UPDATE; IF FOUND THEN IF e.submitted_by IS DISTINCT FROM auth.uid() AND NOT pe_finance_access(e.entity_id) THEN RAISE EXCEPTION ''Forbidden''; END IF; RETURN jsonb_build_object(''id'',e.id,''reused'',true); END IF; END IF;');
d:=public.pe_replace_once(d,' SELECT * INTO e FROM pm_expenses WHERE pm_expenses.id=eid;',' UPDATE pm_expenses SET intake_key=coalesce(intake_key,nullif(_data->>''intakeKey'','''')) WHERE id=eid; SELECT * INTO e FROM pm_expenses WHERE pm_expenses.id=eid;');
d:=public.pe_replace_once(d,' IF e.purchase_document_id IS NOT NULL AND NOT pe_finance_access(ent) THEN',' IF e.purchase_document_id IS NOT NULL AND EXISTS(SELECT 1 FROM financial_document_payments WHERE document_id=e.purchase_document_id) THEN RAISE EXCEPTION ''Reverse purchase links before changing expense''; END IF; IF e.purchase_document_id IS NOT NULL AND NOT pe_finance_access(ent) THEN');
d:=public.pe_replace_once(d,' n:=(_data->>''costAmount'')::numeric; remaining:=',' IF e.tax_parameters->>''vatRate'' IS NULL OR l.vat_rate IS DISTINCT FROM (e.tax_parameters->>''vatRate'')::numeric THEN RAISE EXCEPTION ''Invoice VAT must match confirmed expense treatment''; END IF; n:=(_data->>''costAmount'')::numeric; remaining:=');
d:=public.pe_replace_once(d,' INSERT INTO project_expense_invoice_allocations(expense_id,line_id,cost_amount,billed_amount,vat_amount,tax_treatment,actor) VALUES(e.id,l.id,n,remaining,coalesce((_data->>''vatAmount'')::numeric,0),e.tax_treatment,auth.uid());',' INSERT INTO project_expense_invoice_allocations(expense_id,line_id,cost_amount,billed_amount,vat_amount,tax_treatment,actor) VALUES(e.id,l.id,n,remaining,round(remaining*l.vat_rate/100,2),e.tax_treatment,auth.uid());');
d:=public.pe_replace_once(d,' n+coalesce((SELECT sum(cost_amount) FROM project_expense_invoice_allocations WHERE expense_id=e.id AND reversed_at IS NULL),0)>e.eur_amount',' n+coalesce((SELECT sum(cost_amount) FROM project_expense_invoice_allocations WHERE expense_id=e.id AND reversed_at IS NULL),0)-coalesce((SELECT sum(c.cost_amount) FROM project_expense_credit_allocations c JOIN project_expense_invoice_allocations a ON a.id=c.invoice_allocation_id JOIN financial_document_lines cl ON cl.id=c.credit_line_id JOIN financial_documents cd ON cd.id=cl.document_id WHERE a.expense_id=e.id AND cd.status NOT IN (''draft'',''cancelled'')),0)>e.eur_amount');
d:=public.pe_replace_once(d,' SELECT * INTO l FROM financial_document_lines WHERE financial_document_lines.id=ia.line_id; SELECT * INTO ip',' SELECT * INTO l FROM financial_document_lines WHERE financial_document_lines.id=ia.line_id; SELECT * INTO d FROM financial_documents WHERE id=l.document_id; IF d.entity_id IS DISTINCT FROM e.entity_id OR d.direction<>''issued'' OR d.doc_type<>''client_invoice'' OR d.status IN (''draft'',''cancelled'') THEN RAISE EXCEPTION ''Choose an issued invoice''; END IF; SELECT * INTO ip');
d:=public.pe_replace_once(d,'>ia.billed_amount+ia.vat_amount THEN','>ia.billed_amount+ia.vat_amount-coalesce((SELECT sum(c.billed_amount+c.vat_amount) FROM project_expense_credit_allocations c JOIN financial_document_lines cl ON cl.id=c.credit_line_id JOIN financial_documents cd ON cd.id=cl.document_id WHERE c.invoice_allocation_id=ia.id AND cd.status NOT IN (''draft'',''cancelled'')),0) THEN');
EXECUTE d;
END $$;
CREATE FUNCTION public.pe_receipt_period_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE p uuid; t bank_transactions; BEGIN FOR p IN SELECT DISTINCT x FROM unnest(ARRAY[CASE WHEN TG_OP<>'INSERT' THEN OLD.payment_id END,CASE WHEN TG_OP<>'DELETE' THEN NEW.payment_id END]) x WHERE x IS NOT NULL LOOP SELECT t0.* INTO t FROM financial_document_payments dp JOIN bank_transactions t0 ON t0.id=dp.bank_transaction_id WHERE dp.id=p FOR UPDATE OF t0; IF FOUND AND fin_bank_tx_in_locked_period(t.bank_account_id,t.transaction_date,t.statement_period_id) THEN RAISE EXCEPTION 'Period is locked'; END IF; END LOOP; IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END $$;
CREATE TRIGGER pe_receipt_period_guard BEFORE INSERT OR UPDATE OR DELETE ON public.project_expense_receipt_allocations FOR EACH ROW EXECUTE FUNCTION public.pe_receipt_period_guard();
CREATE OR REPLACE FUNCTION public.pe_match_purchase(_expense uuid,_tx uuid,_amount numeric) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE e pm_expenses; t bank_transactions; d financial_documents; c payment_cards; p financial_document_payments; prior jsonb; BEGIN
SELECT * INTO e FROM pm_expenses WHERE id=_expense FOR UPDATE; SELECT * INTO t FROM bank_transactions WHERE id=_tx FOR UPDATE; SELECT * INTO d FROM financial_documents WHERE id=e.purchase_document_id FOR UPDATE;
IF e.id IS NULL OR e.workflow_version<>2 OR NOT pe_finance_access(e.entity_id) OR e.payment_source_type='personal' OR t.id IS NULL OR t.entity_id IS DISTINCT FROM e.entity_id OR t.amount>=0 OR t.currency<>'EUR' OR fin_bank_tx_in_locked_period(t.bank_account_id,t.transaction_date,t.statement_period_id) OR d.id IS NULL OR d.entity_id IS DISTINCT FROM e.entity_id OR d.direction<>'received' OR d.status='cancelled' OR d.project_expense_id IS DISTINCT FROM e.id THEN RAISE EXCEPTION 'Invalid purchase match'; END IF;
IF e.payment_source_type='company_account' AND t.bank_account_id IS DISTINCT FROM e.paid_from_account_id THEN RAISE EXCEPTION 'Payment account does not match'; END IF;
IF e.payment_source_type='company_card' THEN SELECT * INTO c FROM payment_cards WHERE id=e.payment_card_id; IF c.bank_account_id IS DISTINCT FROM t.bank_account_id THEN RAISE EXCEPTION 'Payment card account does not match'; END IF; END IF;
SELECT * INTO p FROM financial_document_payments WHERE document_id=d.id AND bank_transaction_id=t.id; IF FOUND AND p.amount=_amount THEN RETURN jsonb_build_object('id',e.id,'reused',true); END IF;
IF EXISTS(SELECT 1 FROM project_expense_invoice_allocations WHERE expense_id=e.id AND reversed_at IS NULL) THEN RAISE EXCEPTION 'Reverse allocations before changing expense'; END IF;
IF _amount IS NULL OR _amount::text IN ('NaN','Infinity','-Infinity') OR _amount<=0 OR _amount IS DISTINCT FROM abs(t.amount) OR fin_tx_open_balance(t.id) IS DISTINCT FROM abs(t.amount) THEN RAISE EXCEPTION 'Purchase match requires the full EUR debit'; END IF;
IF e.original_currency='EUR' AND abs(e.original_amount-_amount)>.01 THEN RAISE EXCEPTION 'EUR purchase amount differs from debit'; END IF;
IF EXISTS(SELECT 1 FROM financial_document_payments WHERE document_id=d.id) THEN RAISE EXCEPTION 'Purchase already has payments; review existing links'; END IF;
prior:=to_jsonb(e); PERFORM set_config('app.pe_action','1',true); PERFORM set_config('app.pm_expense_rpc','1',true);
UPDATE pm_expenses SET eur_amount=_amount,purchase_price=_amount,exchange_rate=_amount/original_amount,exchange_rate_date=t.transaction_date,exchange_rate_source='bank_actual',exchange_evidence=jsonb_build_object('bankTransactionId',t.id,'previous',jsonb_build_object('eur',e.eur_amount,'rate',e.exchange_rate,'source',e.exchange_rate_source,'date',e.exchange_rate_date,'evidence',e.exchange_evidence)) WHERE id=e.id;
INSERT INTO financial_document_payments(document_id,bank_transaction_id,amount,payment_date,method,created_by) VALUES(d.id,t.id,_amount,t.transaction_date,'bank_transfer',auth.uid());
UPDATE bank_transactions SET status='classified',classified_at=now(),classified_by=auth.uid(),reconciled_at=now(),reconciled_by=auth.uid() WHERE id=t.id;
PERFORM pe_event(e.id,'purchaseMatch',prior,(SELECT to_jsonb(z) FROM pm_expenses z WHERE id=e.id),NULL,jsonb_build_object('transactionId',t.id)); RETURN jsonb_build_object('id',e.id); END $$;
CREATE FUNCTION public.pe_invoice_from_expenses(_header jsonb,_lines jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE doc uuid; x jsonb; e pm_expenses; a project_expense_invoice_allocations; l financial_document_lines; c numeric; sold numeric; vr numeric; prepared jsonb:='[]'; credits numeric; received numeric; BEGIN
IF NOT pe_finance_access(current_finance_entity()) THEN RAISE EXCEPTION 'Finance access required'; END IF;
IF _header->>'doc_type' NOT IN ('client_invoice','client_credit_note') THEN RAISE EXCEPTION 'Choose an invoice or credit note'; END IF;
FOR x IN SELECT value FROM jsonb_array_elements(_lines) LOOP
IF x->>'expense_id' IS NOT NULL OR x->>'credit_allocation_id' IS NOT NULL THEN
IF x->>'credit_allocation_id' IS NOT NULL THEN SELECT * INTO a FROM project_expense_invoice_allocations WHERE id=(x->>'credit_allocation_id')::uuid AND reversed_at IS NULL FOR UPDATE; SELECT * INTO l FROM financial_document_lines WHERE id=a.line_id; IF _header->>'doc_type'<>'client_credit_note' OR l.document_id IS DISTINCT FROM (_header->>'original_document_id')::uuid THEN RAISE EXCEPTION 'Select the affected original invoice share'; END IF; SELECT * INTO e FROM pm_expenses WHERE id=a.expense_id FOR UPDATE; ELSE SELECT * INTO e FROM pm_expenses WHERE id=(x->>'expense_id')::uuid FOR UPDATE; IF _header->>'doc_type'<>'client_invoice' THEN RAISE EXCEPTION 'Select the affected original invoice share'; END IF; END IF;
IF e.id IS NULL OR e.workflow_version<>2 OR e.entity_id IS DISTINCT FROM current_finance_entity() OR e.rebill_mode='none' OR e.status='draft' OR e.eur_amount IS NULL OR e.tax_treatment='pending' OR e.tax_confirmed_at IS NULL OR e.tax_parameters->>'vatRate' IS NULL OR (e.payment_source_type='personal' AND e.approval_state<>'approved') OR (_header->>'counterparty_client_id')::uuid IS DISTINCT FROM (SELECT company_id FROM pm_projects WHERE id=e.project_id) THEN RAISE EXCEPTION 'Expense is not ready for invoicing'; END IF;
c:=(x->>'expense_cost')::numeric; IF c IS NULL OR c<=0 OR c::text IN ('NaN','Infinity','-Infinity') THEN RAISE EXCEPTION 'Invalid expense amount'; END IF;
vr:=(e.tax_parameters->>'vatRate')::numeric; IF vr<0 OR vr>100 THEN RAISE EXCEPTION 'Invalid VAT rate'; END IF; sold:=round(c*CASE WHEN e.rebill_mode='markup' THEN 1+e.markup_pct/100 ELSE 1 END,2);
IF x->>'credit_allocation_id' IS NOT NULL THEN
SELECT coalesce(sum(ca.cost_amount),0) INTO credits FROM project_expense_credit_allocations ca JOIN financial_document_lines cl ON cl.id=ca.credit_line_id JOIN financial_documents cd ON cd.id=cl.document_id WHERE ca.invoice_allocation_id=a.id AND cd.status<>'cancelled';
SELECT coalesce(sum(r.amount),0) INTO received FROM project_expense_receipt_allocations r WHERE r.invoice_allocation_id=a.id AND r.reversed_at IS NULL;
IF c+credits>a.cost_amount OR received>round((a.cost_amount-c-credits)/a.cost_amount*(a.billed_amount+a.vat_amount),2) THEN RAISE EXCEPTION 'Reverse affected receipts before crediting this share'; END IF;
END IF;
x:=x||jsonb_build_object('description',e.description,'quantity',1,'unit_price_ex_vat',sold,'vat_rate',vr,'vat_code',e.tax_parameters->>'vatCode','project_id',e.project_id,'reimbursable',false);
END IF; prepared:=prepared||jsonb_build_array(x); END LOOP;
doc:=fin_register_issued_document(_header,prepared);
FOR x IN SELECT value FROM jsonb_array_elements(prepared) LOOP
SELECT * INTO l FROM financial_document_lines WHERE document_id=doc AND sort_order=coalesce((x->>'sort_order')::integer,0);
IF x->>'expense_id' IS NOT NULL THEN PERFORM pe_action('invoice',jsonb_build_object('expenseId',x->>'expense_id','lineId',l.id,'costAmount',x->>'expense_cost','vatAmount',l.vat_amount));
ELSIF x->>'credit_allocation_id' IS NOT NULL THEN
SELECT * INTO a FROM project_expense_invoice_allocations WHERE id=(x->>'credit_allocation_id')::uuid; INSERT INTO project_expense_credit_allocations(invoice_allocation_id,credit_line_id,cost_amount,billed_amount,vat_amount,actor) VALUES(a.id,l.id,(x->>'expense_cost')::numeric,l.amount_ex_vat,l.vat_amount,auth.uid());
END IF; END LOOP; RETURN doc; END $$;
REVOKE ALL ON FUNCTION public.pe_invoice_from_expenses(jsonb,jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.pe_invoice_from_expenses(jsonb,jsonb) TO authenticated;
GRANT INSERT ON public.project_expense_credit_allocations TO authenticated;
CREATE POLICY pe_credits_insert ON public.project_expense_credit_allocations FOR INSERT TO authenticated WITH CHECK(actor=auth.uid() AND EXISTS(SELECT 1 FROM public.project_expense_invoice_allocations a JOIN public.pm_expenses e ON e.id=a.expense_id JOIN public.financial_document_lines l ON l.id=credit_line_id JOIN public.financial_documents d ON d.id=l.document_id WHERE a.id=invoice_allocation_id AND public.pe_finance_access(e.entity_id) AND d.entity_id=e.entity_id AND d.doc_type='client_credit_note'));
CREATE FUNCTION public.pe_credit_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE a project_expense_invoice_allocations; l financial_document_lines; d financial_documents; c numeric; r numeric; BEGIN
SELECT * INTO a FROM project_expense_invoice_allocations WHERE id=NEW.invoice_allocation_id FOR UPDATE; SELECT * INTO l FROM financial_document_lines WHERE id=NEW.credit_line_id; SELECT * INTO d FROM financial_documents WHERE id=l.document_id;
IF a.id IS NULL OR a.reversed_at IS NOT NULL OR d.doc_type<>'client_credit_note' OR d.original_document_id IS DISTINCT FROM (SELECT document_id FROM financial_document_lines WHERE id=a.line_id) OR l.amount_ex_vat IS DISTINCT FROM NEW.billed_amount OR l.vat_amount IS DISTINCT FROM NEW.vat_amount OR NEW.cost_amount/a.cost_amount* a.billed_amount-NEW.billed_amount NOT BETWEEN -.01 AND .01 THEN RAISE EXCEPTION 'Invalid credit allocation'; END IF;
SELECT coalesce(sum(ca.cost_amount),0) INTO c FROM project_expense_credit_allocations ca JOIN financial_document_lines cl ON cl.id=ca.credit_line_id JOIN financial_documents cd ON cd.id=cl.document_id WHERE ca.invoice_allocation_id=a.id AND cd.status<>'cancelled'; SELECT coalesce(sum(amount),0) INTO r FROM project_expense_receipt_allocations WHERE invoice_allocation_id=a.id AND reversed_at IS NULL;
IF c+NEW.cost_amount>a.cost_amount OR r>round((a.cost_amount-c-NEW.cost_amount)/a.cost_amount*(a.billed_amount+a.vat_amount),2) THEN RAISE EXCEPTION 'Reverse affected receipts before crediting this share'; END IF;
RETURN NEW; END $$;
CREATE TRIGGER pe_credit_guard BEFORE INSERT ON public.project_expense_credit_allocations FOR EACH ROW EXECUTE FUNCTION public.pe_credit_guard();
CREATE FUNCTION public.pe_credit_line_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF EXISTS(SELECT 1 FROM project_expense_credit_allocations WHERE credit_line_id=OLD.id) THEN RAISE EXCEPTION 'Expense credit lines are immutable'; END IF; IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END $$;
CREATE TRIGGER pe_credit_line_guard BEFORE UPDATE OR DELETE ON public.financial_document_lines FOR EACH ROW EXECUTE FUNCTION public.pe_credit_line_guard();
CREATE FUNCTION public.pe_expense_settlement_figures(_project uuid DEFAULT NULL) RETURNS TABLE(expense_id uuid,received_net_amount numeric,credited_cost numeric,credited_net numeric,credited_vat numeric,allocated_net numeric,allocated_vat numeric) LANGUAGE sql STABLE SET search_path=public AS $$ SELECT e.id,
coalesce((SELECT sum(r.amount*a.billed_amount/nullif(a.billed_amount+a.vat_amount,0)) FROM project_expense_receipt_allocations r JOIN project_expense_invoice_allocations a ON a.id=r.invoice_allocation_id WHERE a.expense_id=e.id AND a.reversed_at IS NULL AND r.reversed_at IS NULL),0),
coalesce((SELECT sum(c.cost_amount) FROM project_expense_credit_allocations c JOIN project_expense_invoice_allocations a ON a.id=c.invoice_allocation_id JOIN financial_document_lines l ON l.id=c.credit_line_id JOIN financial_documents d ON d.id=l.document_id WHERE a.expense_id=e.id AND a.reversed_at IS NULL AND d.status NOT IN ('draft','cancelled')),0),
coalesce((SELECT sum(c.billed_amount) FROM project_expense_credit_allocations c JOIN project_expense_invoice_allocations a ON a.id=c.invoice_allocation_id JOIN financial_document_lines l ON l.id=c.credit_line_id JOIN financial_documents d ON d.id=l.document_id WHERE a.expense_id=e.id AND a.reversed_at IS NULL AND d.status NOT IN ('draft','cancelled')),0),
coalesce((SELECT sum(c.vat_amount) FROM project_expense_credit_allocations c JOIN project_expense_invoice_allocations a ON a.id=c.invoice_allocation_id JOIN financial_document_lines l ON l.id=c.credit_line_id JOIN financial_documents d ON d.id=l.document_id WHERE a.expense_id=e.id AND a.reversed_at IS NULL AND d.status NOT IN ('draft','cancelled')),0),
coalesce((SELECT sum(a.billed_amount) FROM project_expense_invoice_allocations a WHERE a.expense_id=e.id AND a.reversed_at IS NULL),0),coalesce((SELECT sum(a.vat_amount) FROM project_expense_invoice_allocations a WHERE a.expense_id=e.id AND a.reversed_at IS NULL),0)
FROM pm_expenses e WHERE e.workflow_version=2 AND (_project IS NULL OR e.project_id=_project) $$;
REVOKE ALL ON FUNCTION public.pe_expense_settlement_figures(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.pe_expense_settlement_figures(uuid) TO authenticated;
